/* PNG pHYs stores physical density without resampling image pixels (W3C PNG). */
'use strict';
globalThis.SplitDensity=(()=>{
 const key='split.output-dpi.v1';let dpi=96;try{const saved=Number(localStorage.getItem(key));if(valid(saved))dpi=saved;}catch{}
 function valid(value){return Number.isInteger(value)&&value>=36&&value<=1200;}
 function sync(){if($('outputDpi')!==document.activeElement)$('outputDpi').value=String(dpi);$('densityLabel').textContent=`Densidade · ${dpi} DPI`;for(const button of $('densityPresets').children)button.setAttribute('aria-pressed',String(Number(button.dataset.dpi)===dpi));}
 function set(value,{persist=true,notify=true}={}){value=Number(value);if(!valid(value)){toast('Use um DPI inteiro entre 36 e 1200.');$('outputDpi').value=String(dpi);return false;}dpi=value;if(persist)try{localStorage.setItem(key,String(dpi));}catch{}sync();if(notify)globalThis.SplitProjects?.changed();return true;}
 async function stamp(blob,value=dpi){if(!valid(value))throw Error('Densidade DPI inválida.');const bytes=new Uint8Array(await blob.arrayBuffer()),view=new DataView(bytes.buffer);const signature=[137,80,78,71,13,10,26,10];if(bytes.length<33||!signature.every((v,i)=>bytes[i]===v))throw Error('Não foi possível gravar a densidade do PNG.');const chunk=new Uint8Array(21),cv=new DataView(chunk.buffer),ppm=Math.round(value/.0254);cv.setUint32(0,9);chunk.set([112,72,89,115],4);cv.setUint32(8,ppm);cv.setUint32(12,ppm);chunk[16]=1;cv.setUint32(17,crc32(chunk.subarray(4,17)));const parts=[bytes.subarray(0,8)];let offset=8,inserted=false,ended=false;while(offset+12<=bytes.length){const length=view.getUint32(offset),end=offset+12+length;if(end>bytes.length)throw Error('PNG incompleto.');const type=String.fromCharCode(...bytes.subarray(offset+4,offset+8));if(type!=='pHYs')parts.push(bytes.subarray(offset,end));if(type==='IHDR'&&!inserted){parts.push(chunk);inserted=true;}offset=end;if(type==='IEND'){ended=true;break;}}if(!inserted||!ended)throw Error('PNG incompleto.');return new Blob(parts,{type:'image/png'});}
 $('outputDpi').onchange=event=>set(event.target.value);for(const button of $('densityPresets').children)button.onclick=()=>set(button.dataset.dpi);sync();return{get:()=>dpi,set,sync,stamp};
})();
